using System.Diagnostics;
using System.Reflection;
using System.Runtime.Loader;
using System.Text.Json;
var folder = Path.GetFullPath(args[0]);
AssemblyLoadContext.Default.Resolving += (_, name) => File.Exists(Path.Combine(folder, name.Name + ".dll")) ? AssemblyLoadContext.Default.LoadFromAssemblyPath(Path.Combine(folder, name.Name + ".dll")) : null;
var assembly = AssemblyLoadContext.Default.LoadFromAssemblyPath(Path.Combine(folder, "CardGame.Core.Tests.dll"));
var rows = new List<object>();
foreach (var (type, method) in new[] { ("Fame2017PublicPileChecks", "StoreExchangeDistributionAndReplay"), ("Fame2017WuXianChecks", "BorrowedSwordPairsActualUseAndReplay") })
{
    var run = assembly.GetType(type)!.GetMethod(method)!.CreateDelegate<Action>();
    for (var i = 0; i < (args.Length > 2 ? 2 : 8); i++)
    {
        GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect();
        var bytes = GC.GetTotalAllocatedBytes(true);
        var sw = Stopwatch.StartNew();
        run();
        sw.Stop();
        if (args.Length > 2) Assembly.Load("CardGame.Core").GetType("CardGame.Core.SlowCallPerf")!.GetMethod("Report", BindingFlags.Static | BindingFlags.NonPublic)!.Invoke(null, [type + "/" + i]);
        rows.Add(new { type, iteration = i, ms = sw.Elapsed.TotalMilliseconds, bytes = GC.GetTotalAllocatedBytes(true) - bytes });
        Console.WriteLine($"{type} [{i}]: {sw.Elapsed.TotalMilliseconds:F3} ms");
    }
}
File.WriteAllText(args[1], JsonSerializer.Serialize(rows, new JsonSerializerOptions { WriteIndented = true }));

