using System.Text.Json;
using Microsoft.Diagnostics.Tracing;
using Microsoft.Diagnostics.Tracing.Etlx;
using Microsoft.Diagnostics.Tracing.Parsers.Clr;

if (args.Length < 2) throw new ArgumentException("Usage: AllocationParser <output.json> <existing.nettrace> [...]");
var output = Path.GetFullPath(args[0]);
var results = new List<object>();
foreach (var inputArgument in args.Skip(1))
{
    var input = Path.GetFullPath(inputArgument);
    var providers = new Dictionary<string, long>();
    var allocationNames = new Dictionary<string, long>();
    var types = new Dictionary<string, Totals>();
    long eventCount = 0, allocationCount = 0, sampledBytes = 0;
    int eventsLost;
    DateTime sessionStart;
    double durationMs;
    using (var source = new EventPipeEventSource(input))
    {
        source.AllEvents += data =>
        {
            eventCount++;
            Increment(providers, data.ProviderName);
            if (data.EventName.Contains("alloc", StringComparison.OrdinalIgnoreCase))
                Increment(allocationNames, data.ProviderName + "/" + data.EventName);
        };
        source.Clr.GCAllocationTick += data =>
        {
            allocationCount++;
            var weight = Weight(data);
            sampledBytes += weight;
            var type = string.IsNullOrEmpty(data.TypeName) ? "<not recorded>" : data.TypeName;
            Add(types, type, weight);
        };
        source.Process();
        eventsLost = source.EventsLost;
        sessionStart = source.SessionStartTime.ToUniversalTime();
        durationMs = source.SessionDuration.TotalMilliseconds;
    }

    var stacks = new Dictionary<string, Totals>();
    var applicationSites = new Dictionary<string, Totals>();
    var typedStacks = new Dictionary<string, Totals>();
    long allocationStackCount = 0, allocationStackBytes = 0, etlxAllocationCount = 0;
    if (allocationCount > 0)
    {
        var intermediate = Path.Combine(AppContext.BaseDirectory, Path.GetFileNameWithoutExtension(input) + ".etlx");
        try
        {
            TraceLog.CreateFromEventPipeDataFile(input, intermediate, new TraceLogOptions
            {
                LocalSymbolsOnly = true, AlwaysResolveSymbols = false, KeepAllEvents = true
            });
            using var log = new TraceLog(intermediate);
            using var source = log.Events.GetSource();
            source.Clr.GCAllocationTick += data =>
            {
                etlxAllocationCount++;
                var stack = log.GetCallStackForEvent(data);
                if (stack is null) return;
                var frames = new List<string>();
                for (var depth = 0; stack is not null && depth < 64; depth++, stack = stack.Caller)
                {
                    var address = stack.CodeAddress;
                    var method = address.FullMethodName;
                    frames.Add(string.IsNullOrEmpty(method)
                        ? $"<unresolved:{address.ModuleName}+0x{address.Address:x}>" : method);
                }
                allocationStackCount++;
                var weight = Weight(data);
                allocationStackBytes += weight;
                var text = string.Join("\n", frames);
                Add(stacks, text, weight);
                Add(typedStacks, (string.IsNullOrEmpty(data.TypeName) ? "<not recorded>" : data.TypeName) + "\n" + text, weight);
                var application = frames.FirstOrDefault(frame => frame.StartsWith("CardGame.", StringComparison.Ordinal));
                if (application is not null) Add(applicationSites, application, weight);
            };
            source.Process();
        }
        finally
        {
            if (File.Exists(intermediate)) File.Delete(intermediate);
        }
    }

    results.Add(new
    {
        Trace = Path.GetFileName(input), TraceBytes = new FileInfo(input).Length,
        SessionStartUtc = sessionStart, DurationMs = durationMs, EventCount = eventCount, EventsLost = eventsLost,
        Providers = providers.OrderByDescending(pair => pair.Value).Select(pair => new { Provider = pair.Key, Events = pair.Value }),
        AllocationNamedEvents = allocationNames,
        GCAllocationTickEvents = allocationCount, SampledAllocatedBytes = sampledBytes,
        IndexedAllocationEvents = etlxAllocationCount, AllocationEventsWithStack = allocationStackCount,
        SampledAllocatedBytesWithStack = allocationStackBytes,
        TopTypes = types.OrderByDescending(pair => pair.Value.Bytes).Take(20).Select(pair => new
        {
            Type = pair.Key, pair.Value.Events, SampledBytes = pair.Value.Bytes,
            PercentOfSampledBytes = sampledBytes == 0 ? 0 : 100d * pair.Value.Bytes / sampledBytes
        }),
        TopAllocationStacks = stacks.OrderByDescending(pair => pair.Value.Bytes).Take(15).Select(pair => new
        {
            pair.Value.Events, SampledBytes = pair.Value.Bytes, FramesLeafToRoot = pair.Key.Split('\n')
        }),
        TopApplicationAllocationSites = applicationSites.OrderByDescending(pair => pair.Value.Bytes).Take(20).Select(pair => new
        {
            Method = pair.Key, pair.Value.Events, SampledBytes = pair.Value.Bytes
        }),
        TopTypedAllocationStacks = typedStacks.OrderByDescending(pair => pair.Value.Bytes).Take(20).Select(pair => new
        {
            Type = pair.Key[..pair.Key.IndexOf('\n')], pair.Value.Events, SampledBytes = pair.Value.Bytes,
            FramesLeafToRoot = pair.Key[(pair.Key.IndexOf('\n') + 1)..].Split('\n')
        })
    });
    Console.WriteLine($"{Path.GetFileName(input)}: {eventCount} events; {allocationCount} GCAllocationTick; {sampledBytes} sampled weighted bytes; {allocationStackCount} allocation stacks.");
}
File.WriteAllText(output, JsonSerializer.Serialize(new
{
    Interpretation = "Diagnostic allocation sampling only; traced durations are not normal performance timings. GCAllocationTick is sampling, and AllocationAmount64 is the allocation interval attributed to the triggering type, not an exact census of bytes of that type. Stacks below come from the allocation event itself, never CPU samples. Symbol resolution is local-only. Zero allocation events means a trace cannot identify allocation types. The continued-phase-allocation trace uses this phase's normal compiled outputs; other trace stages must be identified separately.",
    ParserAssembly = typeof(EventPipeEventSource).Assembly.FullName,
    Traces = results
}, new JsonSerializerOptions { WriteIndented = true }));

static long Weight(GCAllocationTickTraceData data) => data.Version >= 2 ? data.AllocationAmount64 : (uint)data.AllocationAmount;
static void Increment(Dictionary<string, long> values, string key) => values[key] = values.GetValueOrDefault(key) + 1;
static void Add(Dictionary<string, Totals> values, string key, long bytes)
{
    if (!values.TryGetValue(key, out var total)) values[key] = total = new();
    total.Events++;
    total.Bytes += bytes;
}
sealed class Totals { public long Events; public long Bytes; }
